code='''def transform(grid):
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    # The five-cell horizontal exemplar is the strongest non-background window.
    candidates = []
    for r, row in enumerate(grid):
        for c in range(len(row) - 4):
            window = row[c:c+5]
            score = sum(v != bg for v in window)
            if score >= 2:
                candidates.append((score, r, c, window[:]))
    _, _, _, pattern = max(candidates)
    out = [row[:] for row in grid]
    for r, row in enumerate(grid):
        for c, v in enumerate(row):
            if v != bg and v not in pattern:
                # Scatter markers are isolated non-background colors; do not replace exemplar cells.
                if all(grid[rr][cc] == bg for rr, cc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)) if 0 <= rr < len(grid) and 0 <= cc < len(row)):
                    start = c - 2
                    for j, x in enumerate(pattern):
                        out[r][start+j] = x
    return out
